      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      padding: 26px;
    }

    .eyebrow {
      margin: 0 0 8px;
      color: #2563eb;
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
