      display: grid;
    }

    .dialog {
      width: min(100%, 460px);
      border-radius: 28px;
      background: var(--surface);
      box-shadow: 0 30px 90px rgba(0, 0, 0, 0.28);
      animation: enter 180ms ease-out;
    }

    @keyframes enter {
      from {
        opacity: 0;
        transform: translateY(10px) scale(0.98);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
