  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-soft: #f8fafc;
      --text: #111827;
      --muted: #6b7280;
      --border: #e5e7eb;
      --danger: #e11d48;
      --danger-dark: #be123c;
      --shadow: 0 24px 70px rgba(15, 23, 42, 0.16);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at top left, rgba(59, 130, 246, 0.16), transparent 30rem),
        linear-gradient(135deg, #f8fafc 0%, var(--bg) 100%);
      color: var(--text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    button {
      border: 0;
      font: inherit;
      cursor: pointer;
    }

    .page {
      width: min(92vw, 980px);
      padding: 32px;
    }

    .preview-card {
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.75);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.86);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .image-wrap {
      position: relative;
      aspect-ratio: 16 / 10;
      overflow: hidden;
      background: #dbeafe;
    }

    .image-wrap img {
      width: 100%;
      height: 100%;
      display: block;
      object-fit: cover;
    }

    .badge {
      position: absolute;
      top: 20px;
      left: 20px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(17, 24, 39, 0.72);
      color: #fff;
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.02em;
      backdrop-filter: blur(10px);
    }

    .content {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      padding: 26px;
    }

    .eyebrow {
      margin: 0 0 8px;
      color: #2563eb;
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.7rem, 4vw, 2.6rem);
      line-height: 1.05;
    }

    .description {
      max-width: 560px;
      margin: 12px 0 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    .actions {
      display: flex;
      flex-shrink: 0;
      gap: 12px;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 46px;
      padding: 0 18px;
      border-radius: 14px;
      font-weight: 800;
      transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-secondary {
      border: 1px solid var(--border);
      background: var(--surface);
      color: var(--text);
    }

    .button-danger {
      background: var(--danger);
      color: #fff;
      box-shadow: 0 14px 30px rgba(225, 29, 72, 0.28);
    }

    .button-danger:hover {
      background: var(--danger-dark);
    }

    .modal {
      position: fixed;
      inset: 0;
      z-index: 10;
      display: none;
      place-items: center;
      padding: 24px;
      background: rgba(15, 23, 42, 0.58);
      backdrop-filter: blur(8px);
    }

    .modal.is-open {
      display: grid;
    }

    .dialog {
      width: min(100%, 460px);
      border-radius: 28px;
      background: var(--surface);
      box-shadow: 0 30px 90px rgba(0, 0, 0, 0.28);
      animation: enter 180ms ease-out;
    }

    @keyframes enter {
      from {
        opacity: 0;
        transform: translateY(10px) scale(0.98);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    .dialog-content {
      padding: 28px;
    }

    .icon {
      width: 54px;
      height: 54px;
      display: grid;
      place-items: center;
      margin-bottom: 18px;
      border-radius: 18px;
      background: #ffe4e6;
      color: var(--danger);
      font-size: 1.6rem;
      font-weight: 900;
    }

    .dialog h2 {
      margin: 0;
      font-size: 1.5rem;
      letter-spacing: -0.02em;
    }

    .dialog p {
      margin: 12px 0 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      padding: 20px 28px 28px;
    }

    .deleted-toast {
      position: fixed;
      right: 24px;
      bottom: 24px;
      display: none;
      padding: 14px 18px;
      border: 1px solid #bbf7d0;
      border-radius: 16px;
      background: #f0fdf4;
      color: #166534;
      font-weight: 800;
      box-shadow: 0 16px 34px rgba(22, 101, 52, 0.12);
    }

    .deleted-toast.is-visible {
      display: block;
    }

    @media (max-width: 720px) {
      .page {
        padding: 18px;
      }

      .content,
      .dialog-actions {
        flex-direction: column;
        align-items: stretch;
      }

      .actions {
        flex-direction: column;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="preview-card" aria-labelledby="image-title">
      <div class="image-wrap">
        <img
          src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
          alt="A peaceful lakeside cabin surrounded by pine trees at sunset"
        >
        <span class="badge">Library image</span>
      </div>

      <div class="content">
        <div>
          <p class="eyebrow">Image preview</p>
          <h1 id="image-title">Lakeside retreat</h1>
          <p class="description">
            Review your saved image before managing it in your library. Deleting it will remove this image from your collection.
          </p>
        </div>

        <div class="actions">
          <button class="button button-secondary" type="button">Download</button>
          <button class="button button-danger trigger" type="button" aria-haspopup="dialog">
            Delete image
          </button>
        </div>
      </div>
    </section>
  </main>

  <div class="modal" id="delete-modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog">
      <div class="dialog-content">
        <div class="icon" aria-hidden="true">!</div>
        <h2 id="dialog-title">Delete this image?</h2>
        <p id="dialog-description">
          This will permanently remove "Lakeside retreat" from your library. This action cannot be undone.
        </p>
      </div>

      <div class="dialog-actions">
        <button class="button button-secondary" type="button" data-close-modal>Cancel</button>
        <button class="button button-danger" type="button" id="confirm-delete">Delete image</button>
      </div>
    </div>
  </div>

  <div class="deleted-toast" id="deleted-toast" role="status" aria-live="polite">
    Image deleted from library.
  </div>

  <script>
    const trigger = document.querySelector(".trigger");
    const modal = document.querySelector("#delete-modal");
    const closeButtons = document.querySelectorAll("[data-close-modal]");
    const confirmDelete = document.querySelector("#confirm-delete");
    const toast = document.querySelector("#deleted-toast");

    function openModal() {
      modal.classList.add("is-open");
      confirmDelete.focus();
    }

    function closeModal() {
      modal.classList.remove("is-open");
      trigger.focus();
    }

    trigger.addEventListener("click", openModal);

    closeButtons.forEach((button) => {
      button.addEventListener("click", closeModal);
    });

    modal.addEventListener("click", (event) => {
      if (event.target === modal) {
        closeModal();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && modal.classList.contains("is-open")) {
        closeModal();
      }
    });

    confirmDelete.addEventListener("click", () => {
      closeModal();
      toast.classList.add("is-visible");
    });
  </script>
</body>
</html>
